text:
{
 "title": "日・アルゼンチン租税条約",
 "lead": {
  "es": "日本《にほん》とアルゼンチンで、同《おな》じもうけに税金《ぜいきん》が2回《かい》かからないようにする約束《やくそく》です。",
  "hs": "人やお金の行き来で生じる二重課税（同じ所得に2つの国で税がかかること）をなくすため、日本とアルゼンチンの間で課税権を調整する条約。",
  "std": "人的交流や経済的交流に伴って生じる国際的な二重課税をなくすため、日本とアルゼンチンの間で課税権を調整する条約。",
  "univ": "人的交流及び経済的交流に伴って発生する国際的な二重課税の除去を目的として、我が国とアルゼンチンとの間で課税権を調整する条約。"
 },
 "facts": [
  {
   "es": "この約束《やくそく》は、日本《にほん》かアルゼンチンに住《す》む人《ひと》や会社《かいしゃ》の、もうけにかかる税金《ぜいきん》についてのものです。会社《かいしゃ》が相手《あいて》の国《くに》に店《みせ》などを持《も》っていることがあります。そのときは、その店《みせ》などのもうけにだけ、相手《あいて》の国《くに》が税金《ぜいきん》をかけられます。※正確《せいかく》には、相手《あいて》の国《くに》の「恒久的施設《こうきゅうてきしせつ》に帰《き》せられる利得《りとく》についてのみ」課税《かぜい》できます。",
   "hs": "条約は、どちらかまたは両方の国の居住者の、所得にかかる税について使われる。ある国の企業《きぎょう》が相手の国に恒久的施設《こうきゅうてきしせつ》（事業を行う一定の場所）を持つ場合、相手の国は、その施設《しせつ》のもうけ（事業利得）にだけ税をかけられる。",
   "std": "条約は、一方または両方の締約国の居住者に対し、所得に対する租税について適用する。一方の締約国の企業の事業利得は、その企業が相手国内に恒久的施設を持つ場合、その恒久的施設に帰せられる利得に限り、相手国で課税できる。",
   "univ": "この条約は、一方又は双方の締約国の居住者に対し、所得に対する租税について適用する。一方の締約国の企業の事業利得については、当該企業が他方の締約国内に恒久的施設を有する場合には、当該恒久的施設に帰せられる利得についてのみ当該他方の締約国において課税することができる。"
  },
  {
   "es": "配当《はいとう》（株《かぶ》のもうけ）、利子《りし》、使用料《しようりょう》の税金《ぜいきん》についてのきまりです。お金《かね》が生《う》まれた国《くに》は、決《き》められた上限《じょうげん》までしか税金《ぜいきん》をかけないか、かけません。それでも2つの国《くに》で税金《ぜいきん》がかかるときは、住《す》んでいる国《くに》のほうでなくします。※正確《せいかく》には「源泉地国《げんせんちこく》において限度税率《げんどぜいりつ》の範囲《はんい》で課税《かぜい》することができること又《また》は免税《めんぜい》とすること」を定《さだ》めます。",
   "hs": "配当・利子・使用料については、所得が生まれた国（源泉地国）が税をかけられる。ただし、上限の税率（限度税率）の範囲《はんい》までとするか、税をかけない（免税《めんぜい》）とする。条約による課税で二重に税がかかる場合は、住んでいる国（居住地国）でそれをなくす。",
   "std": "配当、利子、使用料については、源泉地国で限度税率の範囲内で課税できること、または免税とすることを定める。条約の規定による課税で生じる二重課税は、居住地国で除去する。",
   "univ": "配当、利子及び使用料については、源泉地国において限度税率の範囲で課税することができること又は免税とすることを規定する。また、この条約の規定による課税によって生ずる二重課税を居住地国において除去する。"
  },
  {
   "es": "約束《やくそく》に合《あ》わない税金《ぜいきん》をかけられたら、国《くに》の係《かかり》の役所《やくしょ》に申《もう》し出《で》ることができます。そして、2つの国《くに》の役所《やくしょ》が話《はな》し合《あ》って解決《かいけつ》します。",
   "hs": "条約のきまりに合わない課税があったときは、担当の役所（権限のある当局）に申し立てができる。そして、両国の当局どうしの話し合いで解決するしくみを定める。",
   "std": "条約の規定に合わない課税について、権限のある当局への申し立てと、当局間の協議による解決を定める。",
   "univ": "この条約の規定に適合しない課税について、権限のある当局に対する申立て及び権限のある当局間での協議による解決について規定する。"
  },
  {
   "es": "2つの国《くに》の役所《やくしょ》は、税金《ぜいきん》についての情報《じょうほう》を交換《こうかん》します。また、はらわれていない税金《ぜいきん》を、おたがいに手伝《てつだ》って集《あつ》めるきまりをつくります。※正確《せいかく》には「滞納租税債権一般《たいのうそぜいさいけんいっぱん》を対象《たいしょう》とする徴収共助《ちょうしゅうきょうじょ》の規定《きてい》を導入《どうにゅう》」し、その要件《ようけん》や手続《てつづ》きなども定《さだ》めます。",
   "hs": "両国の当局どうしで、税に関する情報を交換《こうかん》する。また、はらわれていない税（滞納《たいのう》された税）全般について、徴収共助《ちょうしゅうきょうじょ》のきまりを取り入れる。これは相手の国にかわって税の取り立てを手伝うしくみで、その要件や手続きなども定める。",
   "std": "両国の権限のある当局の間で租税に関する情報を交換する。また、滞納された租税債権全般を対象とする徴収共助の規定を導入し、その実施のための要件や手続きなどを定める。",
   "univ": "両締約国の権限のある当局間で租税に関する情報を交換する。また、滞納租税債権一般を対象とする徴収共助の規定を導入し、その実施のための要件、手続等を規定する。"
  },
  {
   "es": "この約束《やくそく》で得《とく》をするしくみが、悪《わる》く使《つか》われないようにします。ほかの国《くに》にある店《みせ》などのもうけにかかる税金《ぜいきん》が、決《き》められた額《がく》より少《すく》ないときは、使《つか》えません。得《とく》をすることがおもな目的《もくてき》の取《と》り引《ひ》きなども、使《つか》えません。※正確《せいかく》には、それらの場合《ばあい》に「条約《じょうやく》の特典《とくてん》は与《あた》えられない」というきまりです。",
   "hs": "条約の特典（条約で受けられる有利なあつかい）を悪用されないよう、次の場合は特典を与《あた》えない。1つは、第三国にある恒久的施設《こうきゅうてきしせつ》の所得に第三国でかかる税の額が、一定の額に満たない場合。もう1つは、取り引きなどの主な目的が特典を受けることである場合。",
   "std": "条約の特典の濫用を防ぐため、第三国にある恒久的施設に帰属する所得について第三国で課される税額が一定の額に満たない場合と、取引などの主要な目的が条約の特典を受けることである場合には、条約の特典を与えない。",
   "univ": "この条約の特典の濫用を防止するため、第三国に存在する恒久的施設に帰属する所得について第三国において課される租税の額が一定の額に満たない場合及び取引等の主要な目的が条約の特典を受けることである場合には条約の特典は与えられない。"
  },
  {
   "es": "両方《りょうほう》の国《くに》は、それぞれのきまりにそって、この約束《やくそく》を認《みと》めます。認《みと》めたことを文書《ぶんしょ》で知《し》らせ合《あ》った日《ひ》の後《あと》、30日目《にちめ》の日《ひ》から使《つか》われ始《はじ》めます。※正確《せいかく》には「承認《しょうにん》を通知《つうち》する外交上《がいこうじょう》の公文《こうぶん》の交換《こうかん》の日《ひ》の後《のち》30日目《にちめ》の日《ひ》」に効力《こうりょく》を生《しょう》じます。",
   "hs": "条約は、両国がそれぞれの法令の手続きにしたがって承認する。承認を知らせる外交上の公文（公式の文書）を交換《こうかん》した日の後30日目の日に、条約は効力を生じる（使われ始める）。",
   "std": "条約は、両国それぞれの法令上の手続きに従って承認され、その承認を通知する外交上の公文を交換した日の後30日目の日に効力を生じる。",
   "univ": "この条約は、両締約国のそれぞれの法令上の手続に従って承認されるものとし、その承認を通知する外交上の公文の交換の日の後30日目の日に効力を生ずる。"
  }
 ]
}
